import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"命令与权限","description":"","frontmatter":{},"headers":[],"relativePath":"modules/corelib/commands.md","filePath":"modules/corelib/commands.md","lastUpdated":0}`),a={name:`modules/corelib/commands.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="命令与权限" tabindex="-1">命令与权限 <a class="header-anchor" href="#命令与权限" aria-label="Permalink to “命令与权限”">​</a></h1><p>EmakiCoreLib 的主命令是 <code>/emakicorelib</code>，别名为 <code>/corelib</code>、<code>/emakicore</code>。这些命令主要面向服务器管理员，用于重载 CoreLib、执行配置预检、查看或执行已注册 Action，以及排查循环 Action 任务。</p><h2 id="命令列表" tabindex="-1">命令列表 <a class="header-anchor" href="#命令列表" aria-label="Permalink to “命令列表”">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>说明</th><th>权限</th></tr></thead><tbody><tr><td><code>/corelib reload</code></td><td>重载 CoreLib 配置与 Action 系统；预检失败时取消本次重载并保留旧配置。</td><td><code>emakicorelib.reload</code> 或 <code>emakicorelib.admin</code></td></tr><tr><td><code>/corelib check [module|report|--fix]</code></td><td>执行配置预检、检查指定模块或查看最近一次报告；当前版本的 <code>--fix</code> 为只读提示，不执行自动修复。</td><td><code>emakicorelib.admin</code></td></tr><tr><td><code>/corelib action list</code></td><td>列出当前已注册段的 id、kind（<code>source</code>/<code>gate</code>/<code>action</code>）与 owner。</td><td><code>emakicorelib.admin</code></td></tr><tr><td><code>/corelib action run &lt;actionId&gt; key=value ...</code></td><td>直接执行一条当前已注册的 Action；也支持 <code>/corelib action &lt;actionId&gt; key=value ...</code> 简写。</td><td><code>emakicorelib.admin</code></td></tr><tr><td><code>/corelib pdc-convert &lt;players|containers|entities|all&gt; [--dry-run]</code></td><td>把历史带点 PDC 键转换为扁平键；<code>--dry-run</code> 只统计不写入。</td><td><code>emakicorelib.admin</code></td></tr><tr><td><code>/corelib debug all [on|off|status]</code></td><td>运行时切换全局 Debug 开关；不带参数等同 <code>status</code>。重载后恢复为 <code>debug.global_all</code> 的配置值。</td><td><code>emakicorelib.admin</code></td></tr><tr><td><code>/corelib debug loops [list|player|key|cancel|cancel-player]</code></td><td>查看活动循环 Action 任务，并按 key 或玩家取消循环任务。</td><td><code>emakicorelib.admin</code></td></tr><tr><td><code>/corelib help</code></td><td>显示子命令帮助；不带参数或输入未知子命令时也会显示。</td><td>无</td></tr></tbody></table><p><code>action</code> 子命令可写作 <code>actions</code>，两者等价。</p><h2 id="权限节点" tabindex="-1">权限节点 <a class="header-anchor" href="#权限节点" aria-label="Permalink to “权限节点”">​</a></h2><table tabindex="0"><thead><tr><th>权限</th><th>默认</th><th>说明</th></tr></thead><tbody><tr><td><code>emakicorelib.reload</code></td><td>op</td><td>允许重载 CoreLib。</td></tr><tr><td><code>emakicorelib.admin</code></td><td>op</td><td>CoreLib 管理员总权限，包含 <code>emakicorelib.reload</code>。</td></tr></tbody></table><h2 id="常用操作" tabindex="-1">常用操作 <a class="header-anchor" href="#常用操作" aria-label="Permalink to “常用操作”">​</a></h2><h3 id="重载-corelib" tabindex="-1">重载 CoreLib <a class="header-anchor" href="#重载-corelib" aria-label="Permalink to “重载 CoreLib”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/corelib reload</span></span></code></pre></div><p>适合修改 CoreLib 主配置、语言文件或 Action 后使用。重载会先执行配置预检；预检失败时不会替换当前正在生效的配置。</p><h3 id="执行配置预检" tabindex="-1">执行配置预检 <a class="header-anchor" href="#执行配置预检" aria-label="Permalink to “执行配置预检”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/corelib check</span></span>
<span class="line"><span>/corelib check report</span></span>
<span class="line"><span>/corelib check corelib</span></span></code></pre></div><p><code>check</code> 会检查配置引用、Action 模板、物品源与 CoreLib 相关配置。<code>report</code> 查看最近一次预检结果；传入模块 ID 时只检查指定模块。</p><h3 id="查看和执行已注册-action" tabindex="-1">查看和执行已注册 Action <a class="header-anchor" href="#查看和执行已注册-action" aria-label="Permalink to “查看和执行已注册 Action”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/corelib action list</span></span>
<span class="line"><span>/corelib action run send_message text=&quot;hello&quot;</span></span></code></pre></div><p><code>action list</code> 用来确认当前注册表里有哪些段，每行输出 id、kind 与 owner 三项。<code>action run</code> 会把整行交给管道编译器按普通管道行解析，因此参数、引号、<code>if &lt;条件&gt; [ ... ]</code> 分支与 gate 写法都与配置文件中的管道行一致。控制台执行时没有玩家上下文，依赖玩家的段会按既有校验失败。</p><h3 id="转换历史-pdc-键" tabindex="-1">转换历史 PDC 键 <a class="header-anchor" href="#转换历史-pdc-键" aria-label="Permalink to “转换历史 PDC 键”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/corelib pdc-convert players</span></span>
<span class="line"><span>/corelib pdc-convert containers</span></span>
<span class="line"><span>/corelib pdc-convert entities</span></span>
<span class="line"><span>/corelib pdc-convert all --dry-run</span></span></code></pre></div><p>scope 取值为 <code>players</code>、<code>containers</code>、<code>entities</code>、<code>all</code>。转换在异步线程扫描，结束后按 scope 输出 scanned / migrated / skipped / failed 计数与总迁移数。加 <code>--dry-run</code> 时只统计不写入，适合先评估影响面。</p><h3 id="排查循环-action" tabindex="-1">排查循环 Action <a class="header-anchor" href="#排查循环-action" aria-label="Permalink to “排查循环 Action”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/corelib debug loops list</span></span>
<span class="line"><span>/corelib debug loops player Steve</span></span>
<span class="line"><span>/corelib debug loops key some-loop-key</span></span>
<span class="line"><span>/corelib debug loops cancel some-loop-key</span></span>
<span class="line"><span>/corelib debug loops cancel-player Steve</span></span></code></pre></div><p>这些命令只用于排查或清理循环 Action。生产服上不建议长期保留大量循环任务调试输出。</p><h3 id="切换全局-debug" tabindex="-1">切换全局 Debug <a class="header-anchor" href="#切换全局-debug" aria-label="Permalink to “切换全局 Debug”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/corelib debug all status</span></span>
<span class="line"><span>/corelib debug all on</span></span>
<span class="line"><span>/corelib debug all off</span></span></code></pre></div><p>作用等同于临时改写 <code>config.yml</code> 的 <code>debug.global_all</code>，会影响所有使用 CoreLib <code>DebugLogger</code> 的 Emaki 模块。该切换不写回配置文件，<code>/corelib reload</code> 后重新采用配置值。</p>`,26)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};